--- Generates and executes a CMake command to configure a build system.
-- @param source    (string) The source directory containing the `CMakeLists.txt` file.
-- @param build     (string) The build directory where generated files will be placed.
-- @param install   (string) The installation directory for compiled binaries.
-- @param generator (string) The CMake generator to use (e.g., `"Ninja"`, `"Unix Makefiles"`, `"Visual Studio 17 2022"`).
-- @param options   (string|nil) Additional CMake options (optional). Defaults to an empty string if not provided.
local function cmakeGenerate(source, build, install, generator, options)
    local command = string.format(
        'cmake -S "%s" -B "%s" ' ..         -- Set CMake source and (project files) build directory
        '-D CMAKE_INSTALL_PREFIX="%s" ' ..  -- Set CMake install target directory
        '-G "%s" ' ..                       -- Choose project files generator
        ' %s ' ..                           -- Add extra options
        '-D CMAKE_RELEASE_POSTFIX="" ' ..   -- Ensure release artifacts have no postfix
        '-D CMAKE_DEBUG_POSTFIX="_d"',      -- Ensure debug artifacts have '_d' postfix, making them recognizable
        source, build, install, generator, options or ""
    )
    safeExecute(command)
end

--- Builds and installs a CMake project.
-- @param build   (string) The build directory where the CMake project has already been generated.
--                This directory contains the build system files generated by CMake (e.g., Makefiles, Visual Studio files).
-- @param config  (string) The build configuration (e.g., `"Release"`, `"Debug"`, etc.) to use during the build and install process.
local function cmakeBuild(build, config)
    local processors = getProcessorCount()
    print("Build and install cmake project using \'" .. processors .. "\' processors.")
    safeExecute(string.format('cmake --build "%s" --config %s --parallel %d', build, config, processors))
    safeExecute(string.format('cmake --install "%s" --config %s', build, config))
end

--- Generates, builds, and installs a CMake project.
-- This function automates the entire process of running CMake to generate build system files,
-- compiling the project, and installing it into a designated directory.
-- @param source    (string) The source directory containing the `CMakeLists.txt` file.
-- @param name      (string) The name of the project (used to determine the build and install directories).
-- @param config    (string) The build configuration (e.g., `"Release"`, `"Debug"`, etc.).
-- @param generator (string) The CMake generator to use (e.g., `"Ninja"`, `"Unix Makefiles"`, `"Visual Studio 17 2022"`).
-- @param options   (string|nil) Additional CMake options (optional). Defaults to an empty string if not provided.
local function cmakeGenerateAndBuild(source, name, config, generator, options)
    local build = path.join(dir.vendorBuilds, name)
    local install = path.join(dir.vendorInstalls, name)

    cmakeGenerate(source, build, install, generator, options)
    cmakeBuild(build, config)
end

--- Copies files from a source directory to a target directory, with optional filtering based on file extensions.
-- This function copies files from the source directory to the target directory, optionally filtering 
-- them based on file extensions. It can also operate recursively, processing subdirectories.
-- @param source            (string)  The source directory from which files are copied.
-- @param target            (string)  The target directory where files are copied to.
-- @param postfixFilters    (table)   A list of file extensions (strings) to filter files by. 
--                                    Extensions are case-insensitive (e.g., `.txt`, `.jpg`).
-- @param postfixInclusive  (boolean) If true, only files with extensions in `postfixFilters` are copied. 
--                                    If false, files with extensions *not* in `postfixFilters` are copied.
-- @param recursive         (boolean) If true, the function will process subdirectories of the source directory.
local function copySource(source, target, postfixFilters, postfixInclusive, recursive)
    touchDir(target)

    local filters = {}
    for _, ext in ipairs(postfixFilters or {}) do
        filters[string.lower(ext)] = true
    end

    local files = os.matchfiles(path.join(source, "*"))
    for _, file in ipairs(files) do
        local ext = string.lower(path.getextension(file))
        local shouldCopy = postfixInclusive and filters[ext] or (not postfixInclusive and not filters[ext])

        if shouldCopy then
            local filename = path.getname(file)
            local destination = path.join(target, filename)
            os.copyfile(file, destination)

            local rootEscaped = dir.root:gsub("([%.%-])", "%%%1")
            local relativSource = tostring(file):gsub(rootEscaped, "")
            printf('Copied file: ".%s"', relativSource)
        end
    end

    if recursive then
        local directories = os.matchdirs(path.join(source, "*"))
        for _, dir in ipairs(directories) do
            local dirname = path.getname(dir)
            copySource(dir, path.join(target, dirname), postfixFilters, postfixInclusive, recursive)
        end
    end
end

--- Prepares the target directories required for the build process.
-- Ensures that necessary directories for generated files, vendor builds, and vendor installations exist.
-- This function creates the required directories if they are missing.
local function prepTarget()
    touchDir(dir.generated)
    touchDir(dir.vendorBuilds)
    touchDir(dir.vendorInstalls)
end

